I put this:<p><pre><code>  with Ada.Text_IO;

  procedure WTF
  is

    type X is array (Positive range <>) of Integer;

    procedure Print (N: X)
    is
    begin
      for I in N loop
        Ada.Text_IO.Put_Line
          (File => Ada.Text_IO.Standard_Output,
           Item => Integer'Image (N (I));
      end loop;
    end Print;

  begin
    null;
  end WTF;
</code></pre>
